def validate_record(record):
    def edad(v):
        if v is None: return {"status":"review","code":"MISSING","message":"edad ausente"}
        if not isinstance(v, int): return {"status":"reject","code":"BAD_TYPE","message":"edad debe ser int"}
        if v < 0 or v > 120: return {"status":"reject","code":"OUT_OF_RANGE","message":"edad fuera de 0–120"}
        if v < 18: return {"status":"review","code":"NEEDS_REVIEW","message":"edad requiere revisión"}
        return {"status":"accept","code":"OK","message":"edad OK"}
    def region(v):
        if v is None: return {"status":"review","code":"MISSING","message":"region ausente"}
        if v not in {"Lima","Arequipa","Cusco","Piura"}: return {"status":"review","code":"NOT_IN_ALLOWLIST","message":"region requiere revisión"}
        return {"status":"accept","code":"OK","message":"region OK"}
    def monto(v):
        if v is None: return {"status":"review","code":"MISSING","message":"monto ausente"}
        if not isinstance(v, int): return {"status":"reject","code":"BAD_TYPE","message":"monto debe ser int"}
        if v < 0: return {"status":"reject","code":"OUT_OF_RANGE","message":"monto negativo"}
        if v > 50000: return {"status":"review","code":"NEEDS_REVIEW","message":"monto requiere revisión"}
        return {"status":"accept","code":"OK","message":"monto OK"}
    fields = {"edad": edad(record.get("edad")), "region": region(record.get("region")), "monto_ingreso": monto(record.get("monto_ingreso"))}
    statuses = [x["status"] for x in fields.values()]
    status = "reject" if "reject" in statuses else "review" if "review" in statuses else "accept"
    return {"status": status, "fields": fields}

def process_batch(records):
    summary = {"n_total":0,"n_accept":0,"n_reject":0,"n_review":0,"tasa_reject":None,"results":[]}
    for record in records:
        checked = validate_record(record)
        status = checked["status"]
        summary["n_total"] += 1
        summary["n_" + status] += 1
        summary["results"].append({"raw": record.copy(), "status": status, "fields": checked["fields"]})
    if summary["n_total"]:
        summary["tasa_reject"] = summary["n_reject"] / summary["n_total"]
    return summary

def format_report(s):
    return f"total {s['n_total']} accept {s['n_accept']} reject {s['n_reject']} review {s['n_review']} tasa_reject {s['tasa_reject']}"
